function rotatedMin(nums: number[]): number {
  let lo = 0, hi = nums.length - 1; // the minimum is in nums[lo..hi]
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] > nums[hi]) lo = mid + 1; // the drop is after mid
    else hi = mid; // mid may be the minimum
  }
  return nums[lo];
}

