class Solution:
    def rotatedMin(self, nums: List[int]) -> int:
        lo, hi = 0, len(nums) - 1  # the minimum is in nums[lo..hi]
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1  # the drop is after mid
            else:
                hi = mid  # mid may be the minimum
        return nums[lo]

